import json
import sys

path = sys.argv[1]
lo, hi, width = int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4])
with open(path) as f:
    lines = f.read().splitlines()


def flat(o):
    if isinstance(o, str):
        return o
    if isinstance(o, list):
        return " | ".join(flat(x) for x in o)
    if isinstance(o, dict):
        t = o.get("type")
        if t == "text":
            return o.get("text", "")
        if t == "tool_use":
            return "TOOL " + o.get("name", "") + " " + json.dumps(o.get("input", {}))
        if t == "tool_result":
            return "RESULT " + flat(o.get("content", ""))
        if t == "thinking":
            return "THINK " + o.get("thinking", "")
        return json.dumps(o)
    return str(o)


for i, line in enumerate(lines[lo:hi], start=lo):
    try:
        d = json.loads(line)
    except Exception:
        print(i, "unparsed", line[:80])
        continue
    msg = d.get("message", d)
    role = d.get("type") or msg.get("role")
    body = flat(msg.get("content", msg))
    print(i, role, body.replace("\n", " ")[:width])

